// TWO POINTERS TEMPLATE
void twoPointers(vector<int>& arr) {
    int left = 0, right = arr.size() - 1;

    while (left < right) {
        int sum = arr[left] + arr[right];

        if (sum == target) {
            // found answer
            left++; right--;
        } else if (sum < target) {
            left++;   // need bigger sum
        } else {
            right--;  // need smaller sum
        }
    }
}

// VARIANT: Fast & Slow (Floyd's Cycle)
bool hasCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

// FIXED SIZE SLIDING WINDOW
int maxSumSubarrayOfSizeK(vector<int>& arr, int k) {
    int maxSum = 0, windowSum = 0;

    for (int i = 0; i < arr.size(); i++) {
        windowSum += arr[i];
        if (i >= k - 1) {
            maxSum = max(maxSum, windowSum);
            windowSum -= arr[i - (k - 1)];
        }
    }
    return maxSum;
}

// VARIABLE SIZE SLIDING WINDOW (most common in interviews)
int longestSubstringKDistinct(string s, int k) {
    unordered_map<char, int> freq;
    int left = 0, maxLen = 0;

    for (int right = 0; right < s.size(); right++) {
        freq[s[right]]++;

        // shrink window until valid
        while (freq.size() > k) {
            freq[s[left]]--;
            if (freq[s[left]] == 0) freq.erase(s[left]);
            left++;
        }
        maxLen = max(maxLen, right - left + 1);
    }
    return maxLen;
}

// TEMPLATE: Count valid subarrays (atMost trick)
// count(exactly k) = count(atMost k) - count(atMost k-1)
int atMost(vector<int>& arr, int k) {
    unordered_map<int, int> freq;
    int left = 0, count = 0;

    for (int right = 0; right < arr.size(); right++) {
        freq[arr[right]]++;
        while (freq.size() > k) {
            freq[arr[left]]--;
            if (freq[arr[left]] == 0) freq.erase(arr[left]);
            left++;
        }
        count += right - left + 1;
    }
    return count;
}

// STANDARD BINARY SEARCH
int binarySearch(vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2; // avoids overflow

        if (arr[mid] == target) return mid;
        else if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

// LOWER BOUND: first index where arr[i] >= target
int lowerBound(vector<int>& arr, int target) {
    int left = 0, right = arr.size();
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] < target) left = mid + 1;
        else right = mid;
    }
    return left;
}

