// SEARCH IN ROTATED ARRAY
int searchRotated(vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) return mid;

        if (arr[left] <= arr[mid]) { // left half sorted
            if (arr[left] <= target && target < arr[mid]) right = mid - 1;
            else left = mid + 1;
        } else { // right half sorted
            if (arr[mid] < target && target <= arr[right]) left = mid + 1;
            else right = mid - 1;
        }
    }
    return -1;
}

// DFS ON GRAPH (iterative with visited)
void dfs(vector<vector<int>>& adj, int node, vector<bool>& visited) {
    visited[node] = true;
    // process node

    for (int neighbor : adj[node]) {
        if (!visited[neighbor]) {
            dfs(adj, neighbor, visited);
        }
    }
}

// DFS ON GRID (4-directional)
int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};

void dfsGrid(vector<vector<char>>& grid, int r, int c) {
    int rows = grid.size(), cols = grid[0].size();
    if (r < 0 || r >= rows || c < 0 || c >= cols) return;
    if (grid[r][c] != '1') return;

    grid[r][c] = '0'; // mark visited

    for (auto& d : dirs)
        dfsGrid(grid, r + d[0], c + d[1]);
}

int numIslands(vector<vector<char>>& grid) {
    int count = 0;
    for (int r = 0; r < grid.size(); r++)
        for (int c = 0; c < grid[0].size(); c++)
            if (grid[r][c] == '1') { dfsGrid(grid, r, c); count++; }
    return count;
}

// DFS ON TREE
int maxDepth(TreeNode* root) {
    if (!root) return 0;
    return 1 + max(maxDepth(root->left), maxDepth(root->right));
}

// DFS FOR CYCLE DETECTION IN DIRECTED GRAPH
// States: 0=unvisited, 1=in stack, 2=done
bool dfsCycle(vector<vector<int>>& adj, int node, vector<int>& state) {
    state[node] = 1;
    for (int nb : adj[node]) {
        if (state[nb] == 1) return true; // back edge = cycle
        if (state[nb] == 0 && dfsCycle(adj, nb, state)) return true;
    }
    state[node] = 2;
    return false;
}

// BFS ON GRAPH
void bfs(vector<vector<int>>& adj, int start) {
    vector<bool> visited(adj.size(), false);
    queue<int> q;

    q.push(start);
    visited[start] = true;

    while (!q.empty()) {
        int node = q.front(); q.pop();
        // process node

        for (int neighbor : adj[node]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                q.push(neighbor);
            }
        }
    }
}

// BFS SHORTEST PATH
vector<int> bfsShortestPath(vector<vector<int>>& adj, int src, int n) {
    vector<int> dist(n, -1);
    queue<int> q;
    q.push(src); dist[src] = 0;

    while (!q.empty()) {
        int node = q.front(); q.pop();
        for (int nb : adj[node]) {
            if (dist[nb] == -1) {
                dist[nb] = dist[node] + 1;
                q.push(nb);
            }
        }
    }
    return dist;
}

// MULTI-SOURCE BFS (e.g. rotten oranges)
void multiSourceBFS(vector<vector<int>>& grid) {
    int rows = grid.size(), cols = grid[0].size();
    queue<pair<int,int>> q;
    int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};

    // push all sources initially
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            if (grid[r][c] == 2) q.push({r, c});

    int time = 0;
    while (!q.empty()) {
        int sz = q.size();
        while (sz--) {
            auto [r, c] = q.front(); q.pop();
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1) {
                    grid[nr][nc] = 2;
                    q.push({nr, nc});
                }
            }
        }
        time++;
    }
}

// LEVEL ORDER TRAVERSAL
vector<vector<int>> levelOrder(TreeNode* root) {
    vector<vector<int>> result;
    if (!root) return result;
    queue<TreeNode*> q;
    q.push(root);

    while (!q.empty()) {
        int sz = q.size();
        vector<int> level;
        while (sz--) {
            auto node = q.front(); q.pop();
            level.push_back(node->val);
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        result.push_back(level);
    }
    return result;
}

// TOP-DOWN (Memoization) TEMPLATE
unordered_map<int, int> memo;

int solve(int n) {
    if (n <= 1) return n; // base case
    if (memo.count(n)) return memo[n]; // check cache

    memo[n] = solve(n-1) + solve(n-2); // recurrence
    return memo[n];
}

// BOTTOM-UP (Tabulation) TEMPLATE
int climbStairs(int n) {
    if (n <= 2) return n;
    vector<int> dp(n + 1);
    dp[1] = 1; dp[2] = 2;

    for (int i = 3; i <= n; i++)
        dp[i] = dp[i-1] + dp[i-2];

    return dp[n];
}

// SPACE OPTIMIZED (when only prev states needed)
int climbStairsOptimized(int n) {
    int prev2 = 1, prev1 = 2;
    for (int i = 3; i <= n; i++) {
        int curr = prev1 + prev2;
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

// LONGEST INCREASING SUBSEQUENCE (O(n log n))
int lis(vector<int>& nums) {
    vector<int> tails; // tails[i] = smallest tail of IS of length i+1

    for (int num : nums) {
        auto it = lower_bound(tails.begin(), tails.end(), num);
        if (it == tails.end()) tails.push_back(num);
        else *it = num;
    }
    return tails.size();
}

// LCS TEMPLATE
int lcs(string s1, string s2) {
    int m = s1.size(), n = s2.size();
    vector<vector<int>> dp(m+1, vector<int>(n+1, 0));

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s1[i-1] == s2[j-1])
                dp[i][j] = 1 + dp[i-1][j-1];
            else
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
        }
    }
    return dp[m][n];
}

// EDIT DISTANCE TEMPLATE
int editDistance(string s1, string s2) {
    int m = s1.size(), n = s2.size();
    vector<vector<int>> dp(m+1, vector<int>(n+1, 0));

    for (int i = 0; i <= m; i++) dp[i][0] = i;
    for (int j = 0; j <= n; j++) dp[0][j] = j;

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s1[i-1] == s2[j-1])
                dp[i][j] = dp[i-1][j-1];
            else
                dp[i][j] = 1 + min({dp[i-1][j],   // delete
                                    dp[i][j-1],   // insert
                                    dp[i-1][j-1]  // replace
                                   });
        }
    }
    return dp[m][n];
}

// GRID DP TEMPLATE (unique paths)
int uniquePaths(int m, int n) {
    vector<vector<int>> dp(m, vector<int>(n, 1));

    for (int i = 1; i < m; i++)
        for (int j = 1; j < n; j++)
            dp[i][j] = dp[i-1][j] + dp[i][j-1];

    return dp[m-1][n-1];
}

// 0/1 KNAPSACK
int knapsack01(vector<int>& weights, vector<int>& values, int capacity) {
    int n = weights.size();
    vector<vector<int>> dp(n+1, vector<int>(capacity+1, 0));

    for (int i = 1; i <= n; i++) {
        for (int w = 0; w <= capacity; w++) {
            dp[i][w] = dp[i-1][w]; // skip item
            if (weights[i-1] <= w)
                dp[i][w] = max(dp[i][w], values[i-1] + dp[i-1][w - weights[i-1]]);
        }
    }
    return dp[n][capacity];
}

// SUBSET SUM (can we achieve sum T?)
bool subsetSum(vector<int>& nums, int target) {
    vector<bool> dp(target+1, false);
    dp[0] = true;

    for (int num : nums)
        for (int j = target; j >= num; j--) // reverse to avoid reuse
            dp[j] = dp[j] || dp[j - num];

    return dp[target];
}

// UNBOUNDED KNAPSACK (item can be reused)
// Coin Change: min coins to make amount
int coinChange(vector<int>& coins, int amount) {
    vector<int> dp(amount+1, INT_MAX);
    dp[0] = 0;

    for (int i = 1; i <= amount; i++) {
        for (int coin : coins) {
            if (coin <= i && dp[i - coin] != INT_MAX)
                dp[i] = min(dp[i], 1 + dp[i - coin]);
        }
    }
    return dp[amount] == INT_MAX ? -1 : dp[amount];
}

// COUNT WAYS (Coin Change 2)
int change(int amount, vector<int>& coins) {
    vector<int> dp(amount+1, 0);
    dp[0] = 1;

    for (int coin : coins)       // outer = items (avoids permutation counting)
        for (int j = coin; j <= amount; j++)
            dp[j] += dp[j - coin];

    return dp[amount];
}

// BACKTRACKING MASTER TEMPLATE
// choose -> explore -> unchoose

// SUBSETS
void subsets(vector<int>& nums, int start, vector<int>& curr, vector<vector<int>>& result) {
    result.push_back(curr); // add at every node

    for (int i = start; i < nums.size(); i++) {
        curr.push_back(nums[i]);         // choose
        subsets(nums, i+1, curr, result); // explore
        curr.pop_back();                  // unchoose
    }
}

// PERMUTATIONS
void permutations(vector<int>& nums, vector<bool>& used, vector<int>& curr, vector<vector<int>>& result) {
    if (curr.size() == nums.size()) { result.push_back(curr); return; }

    for (int i = 0; i < nums.size(); i++) {
        if (used[i]) continue;
        used[i] = true;
        curr.push_back(nums[i]);
        permutations(nums, used, curr, result);
        curr.pop_back();
        used[i] = false;
    }
}

// COMBINATION SUM (can reuse elements)
void combinationSum(vector<int>& candidates, int target, int start, vector<int>& curr, vector<vector<int>>& result) {
    if (target == 0) { result.push_back(curr); return; }
    if (target < 0) return;

    for (int i = start; i < candidates.size(); i++) {
        curr.push_back(candidates[i]);
        combinationSum(candidates, target - candidates[i], i, curr, result); // i (not i+1) = reuse allowed
        curr.pop_back();
    }
}

// COMBINATION SUM II (no reuse, skip duplicates)
void combinationSum2(vector<int>& candidates, int target, int start, vector<int>& curr, vector<vector<int>>& result) {
    if (target == 0) { result.push_back(curr); return; }

    for (int i = start; i < candidates.size(); i++) {
        if (i > start && candidates[i] == candidates[i-1]) continue; // skip duplicates
        if (candidates[i] > target) break;
        curr.push_back(candidates[i]);
        combinationSum2(candidates, target - candidates[i], i+1, curr, result);
        curr.pop_back();
    }
}

// NEXT GREATER ELEMENT (monotonic decreasing stack)
vector<int> nextGreater(vector<int>& nums) {
    int n = nums.size();
    vector<int> result(n, -1);
    stack<int> st; // stores indices

    for (int i = 0; i < n; i++) {
        while (!st.empty() && nums[st.top()] < nums[i]) {
            result[st.top()] = nums[i];
            st.pop();
        }
        st.push(i);
    }
    return result;
}

// PREVIOUS SMALLER ELEMENT
vector<int> prevSmaller(vector<int>& nums) {
    int n = nums.size();
    vector<int> result(n, -1);
    stack<int> st;

    for (int i = 0; i < n; i++) {
        while (!st.empty() && nums[st.top()] >= nums[i]) st.pop();
        if (!st.empty()) result[i] = nums[st.top()];
        st.push(i);
    }
    return result;
}

// LARGEST RECTANGLE IN HISTOGRAM
int largestRectangle(vector<int>& heights) {
    stack<int> st;
    int maxArea = 0;
    heights.push_back(0); // sentinel

    for (int i = 0; i < heights.size(); i++) {
        while (!st.empty() && heights[st.top()] > heights[i]) {
            int h = heights[st.top()]; st.pop();
            int w = st.empty() ? i : i - st.top() - 1;
            maxArea = max(maxArea, h * w);
        }
        st.push(i);
    }
    return maxArea;
}

