// KTH LARGEST (min heap of size K)
int kthLargest(vector<int>& nums, int k) {
    priority_queue<int, vector<int>, greater<int>> minH;

    for (int num : nums) {
        minH.push(num);
        if (minH.size() > k) minH.pop();
    }
    return minH.top();
}

// TOP K FREQUENT
vector<int> topKFrequent(vector<int>& nums, int k) {
    unordered_map<int, int> freq;
    for (int n : nums) freq[n]++;

    // min heap by frequency
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> minH;
    for (auto& [val, cnt] : freq) {
        minH.push({cnt, val});
        if (minH.size() > k) minH.pop();
    }

    vector<int> result;
    while (!minH.empty()) { result.push_back(minH.top().second); minH.pop(); }
    return result;
}

// FIND MEDIAN (two heaps)
class MedianFinder {
    priority_queue<int> maxH; // lower half
    priority_queue<int, vector<int>, greater<int>> minH; // upper half
public:
    void addNum(int num) {
        maxH.push(num);
        minH.push(maxH.top()); maxH.pop();
        if (minH.size() > maxH.size()) { maxH.push(minH.top()); minH.pop(); }
    }
    double findMedian() {
        if (maxH.size() > minH.size()) return maxH.top();
        return (maxH.top() + minH.top()) / 2.0;
    }
};

// TRIE IMPLEMENTATION
struct TrieNode {
    TrieNode* children[26];
    bool isEnd;
    TrieNode() : isEnd(false) { fill(children, children+26, nullptr); }
};

class Trie {
    TrieNode* root;
public:
    Trie() { root = new TrieNode(); }

    void insert(string word) {
        TrieNode* node = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!node->children[idx])
                node->children[idx] = new TrieNode();
            node = node->children[idx];
        }
        node->isEnd = true;
    }

    bool search(string word) {
        TrieNode* node = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!node->children[idx]) return false;
            node = node->children[idx];
        }
        return node->isEnd;
    }

    bool startsWith(string prefix) {
        TrieNode* node = root;
        for (char c : prefix) {
            int idx = c - 'a';
            if (!node->children[idx]) return false;
            node = node->children[idx];
        }
        return true;
    }
};

// UNION FIND WITH PATH COMPRESSION + UNION BY RANK
class UnionFind {
    vector<int> parent, rank;
public:
    UnionFind(int n) : parent(n), rank(n, 0) {
        iota(parent.begin(), parent.end(), 0); // parent[i] = i
    }

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]); // path compression
        return parent[x];
    }

    bool unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false; // already connected = cycle!

        // union by rank
        if (rank[px] < rank[py]) swap(px, py);
        parent[py] = px;
        if (rank[px] == rank[py]) rank[px]++;
        return true;
    }

    bool connected(int x, int y) { return find(x) == find(y); }
};

// USAGE: Count connected components
int countComponents(int n, vector<vector<int>>& edges) {
    UnionFind uf(n);
    int components = n;

    for (auto& e : edges)
        if (uf.unite(e[0], e[1])) components--;

    return components;
}

// KAHN'S ALGORITHM (BFS-based)
vector<int> topoSort(int n, vector<vector<int>>& edges) {
    vector<vector<int>> adj(n);
    vector<int> indegree(n, 0);

    for (auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        indegree[e[1]]++;
    }

    queue<int> q;
    for (int i = 0; i < n; i++)
        if (indegree[i] == 0) q.push(i);

    vector<int> order;
    while (!q.empty()) {
        int node = q.front(); q.pop();
        order.push_back(node);
        for (int nb : adj[node]) {
            if (--indegree[nb] == 0) q.push(nb);
        }
    }
    // if order.size() != n => cycle exists
    return order.size() == n ? order : vector<int>();
}

// DFS-BASED TOPO SORT
void dfsTopoSort(int node, vector<vector<int>>& adj, vector<bool>& visited, stack<int>& st) {
    visited[node] = true;
    for (int nb : adj[node])
        if (!visited[nb]) dfsTopoSort(nb, adj, visited, st);
    st.push(node);
}

vector<int> topoSortDFS(int n, vector<vector<int>>& adj) {
    vector<bool> visited(n, false);
    stack<int> st;
    for (int i = 0; i < n; i++)
        if (!visited[i]) dfsTopoSort(i, adj, visited, st);

    vector<int> order;
    while (!st.empty()) { order.push_back(st.top()); st.pop(); }
    return order;
}

// DIJKSTRA'S ALGORITHM
vector<int> dijkstra(int src, int n, vector<vector<pair<int,int>>>& adj) {
    vector<int> dist(n, INT_MAX);
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq; // {dist, node}

    dist[src] = 0;
    pq.push({0, src});

    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();

        if (d > dist[u]) continue; // stale entry

        for (auto [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

// TREE DP PATTERN: return value bubbles up
// used for: max path sum, diameter, balanced check

// MAX PATH SUM
int maxPath = INT_MIN;

int pathSum(TreeNode* root) {
    if (!root) return 0;

    int left  = max(0, pathSum(root->left));  // ignore negative paths
    int right = max(0, pathSum(root->right));

    maxPath = max(maxPath, left + right + root->val); // path through this node

    return root->val + max(left, right); // return best single arm
}

// DIAMETER
int diameter = 0;

int depth(TreeNode* root) {
    if (!root) return 0;
    int left = depth(root->left);
    int right = depth(root->right);
    diameter = max(diameter, left + right);
    return 1 + max(left, right);
}

// HEIGHT + BALANCED CHECK (combined)
int heightBalanced(TreeNode* root) {
    if (!root) return 0;
    int left = heightBalanced(root->left);
    int right = heightBalanced(root->right);
    if (left == -1 || right == -1 || abs(left - right) > 1) return -1; // unbalanced
    return 1 + max(left, right);
}

// LCA
TreeNode* lca(TreeNode* root, TreeNode* p, TreeNode* q) {
    if (!root || root == p || root == q) return root;
    TreeNode* left  = lca(root->left, p, q);
    TreeNode* right = lca(root->right, p, q);
    if (left && right) return root; // p and q on different sides
    return left ? left : right;
}

// 1D PREFIX SUM
vector<int> buildPrefix(vector<int>& arr) {
    int n = arr.size();
    vector<int> prefix(n+1, 0);
    for (int i = 0; i < n; i++)
        prefix[i+1] = prefix[i] + arr[i];
    return prefix;
}
// range sum [l, r] (0-indexed)
int rangeSum(vector<int>& prefix, int l, int r) {
    return prefix[r+1] - prefix[l];
}

// SUBARRAY SUM = K (prefix + hashmap)
int subarraySum(vector<int>& nums, int k) {
    unordered_map<int, int> prefixCount;
    prefixCount[0] = 1;
    int sum = 0, count = 0;

    for (int num : nums) {
        sum += num;
        if (prefixCount.count(sum - k))
            count += prefixCount[sum - k];
        prefixCount[sum]++;
    }
    return count;
}

// 2D PREFIX SUM
vector<vector<int>> build2DPrefix(vector<vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size();
    vector<vector<int>> p(m+1, vector<int>(n+1, 0));

    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++)
            p[i][j] = grid[i-1][j-1] + p[i-1][j] + p[i][j-1] - p[i-1][j-1];
    return p;
}
// sum of rectangle (r1,c1) to (r2,c2) (0-indexed)
int rectSum(vector<vector<int>>& p, int r1, int c1, int r2, int c2) {
    return p[r2+1][c2+1] - p[r1][c2+1] - p[r2+1][c1] + p[r1][c1];
}

// FREQUENCY MAP
unordered_map<int, int> freq;
for (int num : nums) freq[num]++;

// TWO SUM WITH HASHMAP
vector<int> twoSum(vector<int>& nums, int target) {
    unordered_map<int, int> seen; // val -> index
    for (int i = 0; i < nums.size(); i++) {
        int complement = target - nums[i];
        if (seen.count(complement))
            return {seen[complement], i};
        seen[nums[i]] = i;
    }
    return {};
}

// GROUP ANAGRAMS
vector<vector<string>> groupAnagrams(vector<string>& strs) {
    unordered_map<string, vector<string>> groups;
    for (string& s : strs) {
        string key = s;
        sort(key.begin(), key.end());
        groups[key].push_back(s);
    }
    vector<vector<string>> result;
    for (auto& [k, v] : groups) result.push_back(v);
    return result;
}

// LONGEST CONSECUTIVE SEQUENCE O(n)
int longestConsecutive(vector<int>& nums) {
    unordered_set<int> numSet(nums.begin(), nums.end());
    int longest = 0;

    for (int num : numSet) {
        if (!numSet.count(num - 1)) { // start of a sequence
            int curr = num, length = 1;
            while (numSet.count(curr + 1)) { curr++; length++; }
            longest = max(longest, length);
        }
    }
    return longest;
}

// MERGE INTERVALS
vector<vector<int>> merge(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end()); // sort by start
    vector<vector<int>> result;

    for (auto& interval : intervals) {
        if (result.empty() || result.back()[1] < interval[0]) {
            result.push_back(interval); // no overlap
        } else {
            result.back()[1] = max(result.back()[1], interval[1]); // merge
        }
    }
    return result;
}

// MINIMUM MEETING ROOMS (min heap)
int minMeetingRooms(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end());
    priority_queue<int, vector<int>, greater<int>> minH; // end times

    for (auto& interval : intervals) {
        if (!minH.empty() && minH.top() <= interval[0])
            minH.pop(); // reuse room
        minH.push(interval[1]);
    }
    return minH.size();
}

// NON-OVERLAPPING INTERVALS (min removals)
int eraseOverlapIntervals(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end(), [](auto& a, auto& b) {
        return a[1] < b[1]; // sort by end time (greedy)
    });
    int count = 0, prevEnd = INT_MIN;

    for (auto& interval : intervals) {
        if (interval[0] >= prevEnd) prevEnd = interval[1];
        else count++; // overlap, remove it
    }
    return count;
}

// COMMON BIT TRICKS
bool isPowerOfTwo(int n) { return n > 0 && (n & (n-1)) == 0; }
int countSetBits(int n) { int c = 0; while (n) { n &= (n-1); c++; } return c; } // Brian Kernighan
int getKthBit(int n, int k) { return (n >> k) & 1; }
int setKthBit(int n, int k)   { return n | (1 << k); }
int clearKthBit(int n, int k) { return n & ~(1 << k); }
int toggleKthBit(int n, int k){ return n ^ (1 << k); }

// SINGLE NUMBER (XOR trick: a ^ a = 0, a ^ 0 = a)
int singleNumber(vector<int>& nums) {
    int result = 0;
    for (int num : nums) result ^= num;
    return result;
}

// MISSING NUMBER
int missingNumber(vector<int>& nums) {
    int xorAll = 0;
    for (int i = 0; i <= nums.size(); i++) xorAll ^= i;
    for (int num : nums) xorAll ^= num;
    return xorAll;
}

// GENERATE ALL SUBSETS via bitmask
void allSubsets(vector<int>& nums) {
    int n = nums.size();
    for (int mask = 0; mask < (1 << n); mask++) {
        vector<int> subset;
        for (int i = 0; i < n; i++)
            if (mask & (1 << i)) subset.push_back(nums[i]);
        // use subset
    }
}
